/* ==========================================================================
   1. THEME DEFINITIONS & SYSTEM VARIABLES (6 VARIANTS)
   ========================================================================== */
:root {
    /* Theme 1: Cyber Yellow & Electric Pink (Default Neobrutalism) */
    --bg-color: #FFDE00;
    --surface-color: #FFFFFF;
    --surface-secondary: #FFF9D2;
    --text-color: #000000;
    --accent-primary: #FF3366;
    --accent-secondary: #00F0FF;
    --accent-tertiary: #CCFF00;
    --border-color: #000000;
    --border-width: 4px;
    --shadow-x: 8px;
    --shadow-y: 8px;
    --shadow-color: #000000;
    --radius: 0px;
    --font-heading: 'Lexend Mega', sans-serif;
    --font-body: 'Space Grotesk', sans-serif;
    --badge-bg: #00F0FF;
    --badge-text: #000000;
}

[data-theme="2"] {
    /* Theme 2: Acid Mint & Ultraviolet */
    --bg-color: #A3E4D7;
    --surface-color: #FFFFFF;
    --surface-secondary: #E8F8F5;
    --text-color: #111111;
    --accent-primary: #8

/* ==========================================================================
   2. FIXED VERSION SWITCHER (TOP-RIGHT)
   ========================================================================== */
.version-switcher {
    position: fixed;
    top: 15px;
    right: 15px;
    z-index: 10000;
    background: var(--surface-color);
    border: var(--border-width) solid var(--border-color);
    box-shadow: var(--shadow-x) var(--shadow-y) 0 var(--shadow-color);
    border-radius: var(--radius);
    padding: 8px 12px;
    display: flex;
    align-items: center;
    gap: 8px;
}

.version-switcher label {
    font-family: var(--font-heading);
    font-size: 0.75rem;
    font-weight: 900;
    text-transform: uppercase;
    margin-right: 4px;
}

.version-btn {
    width: 32px;
    height: 32px;
    background: var(--bg-color);
    border: 2px solid var(--border-color);
    color: var(--text-color);
    font-family: var(--font-heading);
    font-weight: 800;
    font-size: 0.9rem;
    cursor: poi

/* ==========================================================================
   3. APP HEADER & NAVIGATION
   ========================================================================== */
.header {
    background: var(--surface-color);
    border-bottom: var(--border-width) solid var(--border-color);
    padding: 15px 30px;
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 20px;
    position: sticky;
    top: 0;
    z-index: 1000;
}

.brand-container {
    display: flex;
    align-items: center;
    gap: 12px;
}

.brand-logo {
    background: var(--accent-primary);
    color: #FFFFFF;
    font-family: var(--font-heading);
    font-size: 1.4rem;
    font-weight: 900;
    padding: 8px 16px;
    border: var(--border-width) solid var(--border-color);
    box-shadow: 4px 4px 0 var(--border-color);
    border-radius: var(--radius);
    display: flex;
    align-items: center;
    gap: 8px;
    text-decoration: none;
}

