/* ==========================================================================
   4. LAYOUT GRID: SIDEBAR & MAIN DASHBOARD
   ========================================================================== */
.dashboard-container {
    display: flex;
    flex: 1;
}

/* Accordion Sidebar */
.sidebar {
    width: 280px;
    background: var(--surface-color);
    border-right: var(--border-width) solid var(--border-color);
    padding: 25px 20px;
    display: flex;
    flex-direction: column;
    gap: 20px;
    flex-shrink: 0;
}

.sidebar-title {
    font-size: 0.85rem;
    color: var(--text-color);
    opacity: 0.7;
    margin-bottom: 5px;
}

.accordion-item {
    border: 3px solid var(--border-color);
    box-shadow: 4px 4px 0 var(--border-color);
    background: var(--surface-secondary);
    border-radius: var(--radius);
    margin-bottom: 12px;
    overflow: hidden;
}

.accordion-header {
