/* ==========================================================================
   5. DRAGGABLE WIDGET GRID & KPI METRIC CARDS
   ========================================================================== */
.widget-grid {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 20px;
}

/* Drag & Drop Visual Indication */
.draggable-card {
    cursor: grab;
    user-select: none;
    position: relative;
}

.draggable-card:active {
    cursor: grabbing;
}

.draggable-card.dragging {
    opacity: 0.4;
    transform: scale(0.98);
    border-style: dashed;
}

.draggable-card.drag-over {
    border: 4px dashed var(--accent-primary) !important;
    box-shadow: 0 0 15px var(--accent-primary) !important;
}

.kpi-card {
    background: var(--surface-color);
    border: var(--border-width) solid var(--border-color);
    box-shadow: var(--shadow-x) var(--shadow-y) 0 var(--shadow-color);
    border-radius: var(--radius);
    padding: 20px;
    display: flex;
    flex-direction: column

/* ==========================================================================
   6. SKELETON LOADING EFFECTS
   ========================================================================== */
.skeleton {
    pointer-events: none;
    position: relative;
    overflow: hidden;
}

.skeleton-block {
    background: linear-gradient(90deg, var(--surface-secondary) 25%, var(--bg-color) 50%, var(--surface-secondary) 75%);
    background-size: 200% 100%;
    animation: loading-stripes 1.2s infinite ease-in-out;
    border: 2px solid var(--border-color);
    border-radius: 4px;
}

@keyframes loading-stripes {
    0% { background-position: 200% 0; }
    100% { background-position: -200% 0; }
}

/* Hide elements when skeleton active */
.skeleton-active .kpi-value,
.skeleton-active .kpi-trend,
.skeleton-active svg.chart-svg {
    opacity: 0.1;
}

.skeleton-overlay {
    display: none;
    position: absolute;
    top: 0; left: 0; right: 0; bottom: 0;
    background: var(--surface-color);
