/* ==========================================================================
   7. INTERACTIVE SVG CHARTS & TOOLTIPS
   ========================================================================== */
.charts-section {
    display: grid;
    grid-template-columns: 2fr 1fr;
    gap: 20px;
}

.chart-card {
    background: var(--surface-color);
    border: var(--border-width) solid var(--border-color);
    box-shadow: var(--shadow-x) var(--shadow-y) 0 var(--shadow-color);
    border-radius: var(--radius);
    padding: 25px;
    display: flex;
    flex-direction: column;
    position: relative;
}

.chart-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 20px;
}

.chart-title {
    font-size: 1.1rem;
}

.chart-container {
    position: relative;
    width: 100%;
    height: 280px;
}

.chart-svg {
    width: 100%;
    height: 100%;
    overflow: visible;
}

/* Dynamic Tooltip */
