.main-content, .dashboard-container, .chart-card, .widget-card {
    min-width: 0;
}
.header {
    flex-wrap: wrap;
    padding-top: 70px;
}
.header-controls, .dash-top-bar {
    flex-wrap: wrap;
    gap: 12px;
}
.version-switcher {
    max-width: calc(100% - 24px);
    flex-wrap: wrap;
}
.brutal-modal {
    max-height: calc(100dvh - 32px);
    overflow-y: auto;
}
@media (max-width: 900px) {
    .dashboard-container {
        flex-direction: column;
    }
    .sidebar {
        width: 100%;
        border-right: 0;
        border-bottom: var(--border-width) solid var(--border-color);
    }
    .charts-section {
        grid-template-columns: minmax(0, 1fr);
    }
}
@media (max-width: 600px) {
    .header {
